  noise_peaks: { bg:'Шумни пикове', ru:'Шумные пики', uk:'Гучні піки', en:'Loud peaks', de:'Laute Spitzen', fr:'Pics sonores', es:'Picos de ruido', 'es-MX':'Picos de ruido', it:'Picchi di rumore', pt:'Picos de ruído', ar:'ذروات الضجيج', hi:'तेज़ आवाज़ के शिखर', ja:'大きな音のピーク', ky:'Катуу үн чокулары', 'zh-Hant':'高噪音峰值' },
  noise_mic_err: { bg:'Няма достъп до микрофона на това устройство.', ru:'Нет доступа к микрофону на этом устройстве.', uk:'Немає доступу до мікрофона на цьому пристрої.', en:'No microphone access on this device.', de:'Kein Mikrofonzugriff auf diesem Gerät.', fr:'Pas d’accès au micro sur cet appareil.', es:'Sin acceso al micrófono en este dispositivo.', 'es-MX':'Sin acceso al micrófono en este dispositivo.', it:'Nessun accesso al microfono su questo dispositivo.', pt:'Sem acesso ao microfone neste dispositivo.', ar:'لا يمكن الوصول إلى الميكروفون على هذا الجهاز.', hi:'इस डिवाइस पर माइक्रोफ़ोन उपलब्ध नहीं है।', ja:'この端末ではマイクにアクセスできません。', ky:'Бул түзмөктө микрофонго кирүү жок.', 'zh-Hant':'此裝置無法使用麥克風。' },
  noise_threshold: { bg:'Праг „шумно"', ru:'Порог «шумно»', uk:'Поріг «гучно»', en:'“Loud” threshold', de:'Schwelle „laut"', fr:'Seuil « bruyant »', es:'Umbral «ruidoso»', 'es-MX':'Umbral «ruidoso»', it:'Soglia «rumoroso»', pt:'Limite “barulhento”', ar:'عتبة «مرتفع»', hi:'“तेज़” सीमा', ja:'「うるさい」のしきい値', ky:'«Катуу» босогосу', 'zh-Hant':'「吵鬧」門檻' },
  noise_quiet: { bg:'тихо', ru:'тихо', uk:'тихо', en:'quiet', de:'leise', fr:'calme', es:'silencio', 'es-MX':'silencio', it:'silenzio', pt:'silêncio', ar:'هادئ', hi:'शांत', ja:'静か', ky:'тынч', 'zh-Hant':'安靜' },
  noise_loud: { bg:'шумно', ru:'шумно', uk:'гучно', en:'loud', de:'laut', fr:'bruyant', es:'ruidoso', 'es-MX':'ruidoso', it:'rumoroso', pt:'barulhento', ar:'مرتفع', hi:'तेज़', ja:'うるさい', ky:'катуу', 'zh-Hant':'吵鬧' },
  noise_hint: { bg:'Маркери: жълто = шум над прага, червено = сигнал от наблюдението (събуждане, непознат…).', ru:'Метки: жёлтая = шум выше порога, красная = сигнал от наблюдения (проснулся, незнакомец…).', uk:'Позначки: жовта = шум вище порога, червона = сигнал від спостереження (прокинувся, незнайомець…).', en:'Markers: yellow = noise above the threshold, red = alert from the watch (wake, stranger…).', de:'Marker: gelb = Lärm über der Schwelle, rot = Warnung der Überwachung (wach, Fremder…).', fr:'Repères : jaune = bruit au-dessus du seuil, rouge = alerte de la surveillance (réveil, inconnu…).', es:'Marcas: amarillo = ruido sobre el umbral, rojo = aviso de la vigilancia (despierto, desconocido…).', 'es-MX':'Marcas: amarillo = ruido sobre el umbral, rojo = aviso de la vigilancia (despierto, desconocido…).', it:'Segni: giallo = rumore sopra la soglia, rosso = avviso della sorveglianza (sveglio, sconosciuto…).', pt:'Marcas: amarelo = ruído acima do limite, vermelho = alerta da vigilância (acordou, estranho…).', ar:'العلامات: أصفر = ضجيج فوق العتبة، أحمر = تنبيه من المراقبة (استيقاظ، غريب…).', hi:'चिह्न: पीला = सीमा से ऊपर शोर, लाल = निगरानी से अलर्ट (जागा, अजनबी…)।', ja:'マーカー: 黄 = しきい値を超えた音、赤 = 監視からの通知（起床、見知らぬ人…）。', ky:'Белгилер: сары = босогодон жогорку ызы-чуу, кызыл = көзөмөлдөн эскертүү (ойгонду, бейтааныш…).', 'zh-Hant':'標記：黃色＝超過門檻的噪音，紅色＝監看提醒（醒來、陌生人…）。' },

  // --- Грижа: Звуци ---
  snd_intro: { bg:'Приспивни звуци, генерирани на телефона (без файлове, без мрежа). Свирят и когато смениш екрана; таймерът спира сам.', ru:'Убаюкивающие звуки, генерируемые на телефоне (без файлов, без сети). Играют и при смене экрана; таймер останавливает сам.', uk:'Заколисувальні звуки, що генеруються на телефоні (без файлів, без мережі). Грають і при зміні екрана; таймер зупиняє сам.', en:'Soothing sounds generated on the phone (no files, no network). They keep playing when you switch screens; the timer stops them.', de:'Beruhigende Klänge, auf dem Telefon erzeugt (keine Dateien, kein Netz). Sie laufen weiter beim Bildschirmwechsel; der Timer stoppt sie.', fr:'Sons apaisants générés sur le téléphone (sans fichiers, sans réseau). Ils continuent quand vous changez d’écran ; la minuterie les arrête.', es:'Sonidos relajantes generados en el teléfono (sin archivos, sin red). Siguen sonando al cambiar de pantalla; el temporizador los detiene.', 'es-MX':'Sonidos relajantes generados en el teléfono (sin archivos, sin red). Siguen sonando al cambiar de pantalla; el temporizador los detiene.', it:'Suoni rilassanti generati sul telefono (senza file, senza rete). Continuano cambiando schermata; il timer li ferma.', pt:'Sons relaxantes gerados no telefone (sem arquivos, sem rede). Continuam ao trocar de tela; o temporizador os para.', ar:'أصوات مهدّئة تُولَّد على الهاتف (بلا ملفات، بلا شبكة). تستمر عند تبديل الشاشة؛ المؤقّت يوقفها.', hi:'फ़ोन पर बनी सुकून देने वाली ध्वनियाँ (कोई फ़ाइल नहीं, कोई नेटवर्क नहीं)। स्क्रीन बदलने पर भी बजती रहती हैं; टाइमर रोक देता है।', ja:'端末内で生成する安らぎの音（ファイルもネットワークも不要）。画面を切り替えても再生を続け、タイマーで停止します。', ky:'Телефондо жаралган тынчтандыруучу үндөр (файлсыз, тармаксыз). Экранды алмаштырганда да ойнойт; таймер токтотот.', 'zh-Hant':'手機即時產生的安撫聲音（無檔案、無網路）。切換畫面仍會播放；定時器會自動停止。' },
